#!/usr/bin/env bash
set -euo pipefail

# All three image-loading fixes in one PR: hero image no longer lazy-loaded,
# BrownieImage crossfades the snapshot-to-live-data swap instead of popping,
# and product images now get a responsive ~480px thumbnail variant (srcSet)
# so grid tiles don't download the same file as the hero.
#
# NOTE: this supersedes apply_hero_image_priority_load.sh from the previous
# message — it includes that fix plus two more. Use ONLY this script; do not
# also apply/merge apply_hero_image_priority_load.sh, or this one may fail to
# apply (same file, would be a duplicate change).
#
# Clones into an isolated, branch-named directory ("gowebsite-claude-image-loading-fixes") so it can't
# collide with your Codespace's own checkout or leftovers from earlier runs.

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/image-loading-fixes"
DIR="gowebsite-claude-image-loading-fixes"

if [ -d "$DIR" ]; then
  echo "$DIR already exists here (probably from a previous run of this exact script) — remove it first:" >&2
  echo "  rm -rf $DIR" >&2
  exit 1
fi

echo "Cloning fresh main into $DIR..."
git clone "$REPO_URL" "$DIR"
cd "$DIR"
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH in ./$DIR"
echo "Next steps:"
echo "  cd $DIR"
echo "  git push -u origin $BRANCH"
echo "  Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
